# A compacted topic keeps the latest value per key; None is a tombstone
log = [("u1", "alice"), ("u2", "bob"), ("u1", "alice-v2"),
       ("u3", "carol"), ("u2", None), ("u1", "alice-v3")]

print("original log (offset, key, value):")
for off, (k, v) in enumerate(log):
    print(" ", off, k, v)

def compact(records):
    latest = {}
    for off, (k, v) in enumerate(records):
        latest[k] = (off, v)  # a later record replaces the earlier one
    # keep original offsets, drop tombstones (after delete.retention.ms)
    kept = [(off, k, v) for k, (off, v) in latest.items() if v is not None]
    return sorted(kept)

print("after compaction (offsets unchanged):")
for off, k, v in compact(log):
    print(" ", off, k, v)

# A new consumer rebuilds current state from the compacted log
state = {k: v for _, k, v in compact(log)}
print("rebuilt state:", state)

import random

random.seed(7)  # fixed seed so the output is repeatable
BASE, CAP, MAX_ATTEMPTS = 1.0, 30.0, 6

def full_jitter(attempt):
    # wait = random(0, min(cap, base * 2^attempt))
    return random.uniform(0, min(CAP, BASE * 2 ** attempt))

def call_downstream(attempt):
    return attempt >= 4  # pretend it recovers on the 5th try

def handle(message):
    for attempt in range(MAX_ATTEMPTS):
        if call_downstream(attempt):
            print(message, "succeeded on attempt", attempt + 1)
            return
        wait = full_jitter(attempt)
        ceiling = min(CAP, BASE * 2 ** attempt)
        print("attempt", attempt + 1, "failed; wait %.2fs (ceiling %.0fs)" % (wait, ceiling))
    print(message, "-> dead-letter queue")

handle("msg-42")

import sqlite3

db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE orders(id INTEGER PRIMARY KEY, status TEXT);
CREATE TABLE outbox(id INTEGER PRIMARY KEY AUTOINCREMENT, payload TEXT, sent INTEGER DEFAULT 0);
CREATE TABLE inbox(message_id TEXT PRIMARY KEY);
CREATE TABLE shipments(order_id INTEGER);
""")

# Outbox: business change and event are written in ONE transaction
with db:
    db.execute("INSERT INTO orders VALUES (1, 'PAID')")
    db.execute("INSERT INTO outbox(payload) VALUES ('order-1-paid')")

broker = []  # stands in for Kafka/RabbitMQ

def relay(crash_before_mark):
    for row_id, payload in db.execute("SELECT id, payload FROM outbox WHERE sent=0").fetchall():
        broker.append((str(row_id), payload))  # publish
        if crash_before_mark:
            return  # crash: row stays unsent, so it will be published again
        with db:
            db.execute("UPDATE outbox SET sent=1 WHERE id=?", (row_id,))

relay(True)   # first run publishes but dies before marking
relay(False)  # second run publishes again (at-least-once)
print("broker received:", broker)

def consume(message_id, payload):
    try:
        with db:  # inbox insert and effect share one transaction
            db.execute("INSERT INTO inbox VALUES (?)", (message_id,))
            db.execute("INSERT INTO shipments VALUES (1)")
    except sqlite3.IntegrityError:
        print("duplicate", message_id, "skipped")

for mid, payload in broker:
    consume(mid, payload)
print("shipments created:", db.execute("SELECT COUNT(*) FROM shipments").fetchone()[0])
